@Tags(['golden'])
library;

// T-211: Insights v2 Trends goldens, ar + en, light + dark, plus hidden
// amounts. PNGs are generated by the CI `app-regen` workflow (commit message
// tag), not committed from here.

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/core/l10n/date_format.dart';
import 'package:zaghlol/features/insights/presentation/v2/trends_tab.dart';

import '../../../../support/hide_amounts_support.dart';
import 'trends_test_support.dart';

Future<void> _pump(
  WidgetTester tester, {
  required Locale locale,
  required bool dark,
  bool hidden = false,
  bool exchange = false,
}) async {
  await initDateFormatting();
  await tester.binding.setSurfaceSize(const Size(390, 1500));
  addTearDown(() => tester.binding.setSurfaceSize(null));
  await tester.pumpWidget(
    harness(
      const RepaintBoundary(key: ValueKey('golden-root'), child: TrendsTab()),
      locale: locale,
      dark: dark,
      hideAmounts: hidden ? HideAmountsHarness(hidden: true) : null,
      overrides: trendsOverrides(exchange: exchange),
    ),
  );
  await tester.pumpAndSettle();
}

void main() {
  for (final locale in const [Locale('ar', 'EG'), Locale('en')]) {
    for (final dark in [false, true]) {
      final name = '${locale.languageCode}_${dark ? 'dark' : 'light'}';
      testWidgets('insights v2 trends golden $name', (tester) async {
        await _pump(tester, locale: locale, dark: dark);
        await expectLater(
          find.byKey(const ValueKey('golden-root')),
          matchesGoldenFile('../../../../goldens/insights_v2_trends_$name.png'),
        );
      });
    }
    for (final dark in [false, true]) {
      final xn = '${locale.languageCode}_${dark ? 'dark' : 'light'}';
      testWidgets('insights v2 trends exchange golden $xn', (tester) async {
        await _pump(tester, locale: locale, dark: dark, exchange: true);
        await expectLater(
          find.byKey(const ValueKey('golden-root')),
          matchesGoldenFile(
            '../../../../goldens/insights_v2_trends_exchange_$xn.png',
          ),
        );
      });
    }
    final name = '${locale.languageCode}_light';
    testWidgets('insights v2 trends hidden golden $name', (tester) async {
      await _pump(tester, locale: locale, dark: false, hidden: true);
      await expectLater(
        find.byKey(const ValueKey('golden-root')),
        matchesGoldenFile(
          '../../../../goldens/insights_v2_trends_hidden_$name.png',
        ),
      );
    });
  }
}
